package cobra

import "testing"

func TestHeimdallBenchExactValidArgsCountsArgs(t *testing.T) {
	c := &Command{Use: "c", ValidArgs: []string{"one", "two"}, Args: ExactValidArgs(1), Run: func(*Command, []string) {}}
	if err := c.ValidateArgs([]string{"one", "two"}); err == nil {
		t.Fatal("ExactValidArgs(1) accepted two args")
	}
}

